package com.clavis.reader;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.util.zip.*;
final class ChapterListenChecks {
 static int checks;static void check(boolean condition,String message){checks++;if(!condition)throw new AssertionError(message);}
 static String run(Instrumentation test)throws Exception{Context c=test.getTargetContext();File epub=File.createTempFile("chapters-",".epub",c.getCacheDir()),file=null;android.content.SharedPreferences prefs=c.getSharedPreferences("listen",0);String last=prefs.getString("last",null);float speed=ListenService.defaultSpeed(c);
 try{try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(epub))){ReaderChecks.entry(zip,"META-INF/container.xml","<container><rootfiles><rootfile full-path='OPS/book.opf'/></rootfiles></container>");ReaderChecks.entry(zip,"OPS/book.opf","<package><manifest><item id='one' href='one.xhtml'/><item id='two' href='two.xhtml'/><item id='three' href='three.xhtml'/></manifest><spine><itemref idref='one'/><itemref idref='two'/><itemref idref='three'/></spine></package>");for(int n=1;n<=3;n++)ReaderChecks.entry(zip,"OPS/"+new String[]{"one","two","three"}[n-1]+".xhtml","<html><head><title>Chapter "+n+"</title></head><body><h2>Chapter "+n+"</h2><figure><img src='picture.jpg'/><figcaption>Forbidden image caption "+n+"</figcaption></figure><p class='caption'>Another forbidden caption</p><p>Mr. Bennet walked home. He spoke calmly, and the evening was quiet.</p><p>The next chapter continues the story.</p></body></html>");}
 ListenSession story=NarrationBook.epub(epub,"fixture-chapters:"+System.nanoTime(),"Chapter narration verification",0,"");check(story.chapters&&story.starts.size()==3,"EPUB spine produces three chapters");check(!story.text.contains("Forbidden")&&!story.text.contains("forbidden"),"Figure and CSS captions excluded");check(story.text.contains("Bennet walked home"),"Story prose preserved");check(NarrationText.spoken("Mr. Bennet met Mrs. Bennet.").equals("Mister Bennet met Missus Bennet."),"Honorifics spoken naturally");check(story.chapterAt(story.starts.get(1))==1,"Chapter boundary advances");ListenSession legacy=new ListenSession("book:"+android.net.Uri.fromFile(epub)+":0","Legacy book",story.text);legacy.position=legacy.text.indexOf("Mr. Bennet");ListenSession migrated=NarrationBook.upgrade(c,legacy);check(migrated.chapters&&migrated.starts.size()==3&&migrated.text.startsWith("Mr. Bennet"),"Existing page-based reading upgrades at the same passage");String semantic=NarrationBook.prose("<p>A character discussed the caption in a letter.</p><div class='figcenter'><img/><p>Hidden illustration words</p></div>");check(semantic.contains("discussed the caption")&&!semantic.contains("Hidden illustration"),"Ordinary caption word retained; image container removed");java.util.ArrayList<String> chunks=new java.util.ArrayList<>(),labels=new java.util.ArrayList<>();java.util.ArrayList<Integer> indexes=new java.util.ArrayList<>();NarrationBook.split("Chapter I\n\nFirst prose.\n\nChapter II\n\nSecond prose.","Book",0,chunks,labels,indexes);check(chunks.size()==2,"Single HTML spine item splits chapter headings");
 file=ListenSession.file(c,story.key);story.save(file);File launch=file;Instrumentation.ActivityMonitor monitor=test.addMonitor(ListenActivity.class.getName(),null,false);test.runOnMainSync(()->c.startActivity(new Intent(c,ListenActivity.class).putExtra("file",launch.getAbsolutePath()).putExtra("autoplay",false).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));ListenActivity reader=(ListenActivity)monitor.waitForActivityWithTimeout(10000);test.removeMonitor(monitor);check(reader!=null,"Listen reader activity opens");long limit=SystemClock.elapsedRealtime()+30000;while(SystemClock.elapsedRealtime()<limit&&(ListenService.live==null||!ListenService.live.ready||ListenService.live.story==null))SystemClock.sleep(100);ListenService service=ListenService.live;check(service!=null&&service.ready&&service.story!=null,"Chapter session ready");final int[] outlineCount={0},checked={-1};final android.app.AlertDialog[] outline={null};test.runOnMainSync(()->{reader.render();outline[0]=reader.outline();outlineCount[0]=outline[0].getListView().getAdapter().getCount();checked[0]=outline[0].getListView().getCheckedItemPosition();outline[0].getListView().performItemClick(null,2,2);});check(outlineCount[0]==3&&checked[0]==0,"Outline lists chapters and selects the active one");check(service.story.position==service.story.starts.get(2),"Outline selection seeks to the chosen chapter");check(!service.playing,"Outline seek preserves paused state");test.runOnMainSync(()->{service.seek(0);service.setSpeed(1);service.play();});boolean[] snapshot={false,false,false};boolean warmed=false;limit=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<limit){test.runOnMainSync(()->{snapshot[0]=service.story.chapterAt(service.story.position)>=1;snapshot[1]=service.warmingChapter==1&&service.warmedUntil>=service.story.chapterEnd(1);snapshot[2]=service.playing;});warmed|=snapshot[1];if(snapshot[0])break;SystemClock.sleep(100);}check(warmed,"Full next chapter converted ahead of boundary");check(snapshot[0]&&snapshot[2],"Playback automatically advances into next chapter");final int[] geometry=new int[2];test.runOnMainSync(()->{reader.render();android.text.Spanned styled=(android.text.Spanned)reader.passage.getText();geometry[0]=styled.getSpans(0,styled.length(),android.text.style.ForegroundColorSpan.class).length;geometry[1]=reader.dock.getTop()-reader.excerpt.getBottom();service.pause();});check(geometry[0]>0,"Reader emphasizes the active spoken passage");check(geometry[1]>=0,"Bottom player stays below the reading text");return checks+" caption/chapter narration checks passed\n";
 }finally{test.runOnMainSync(()->{if(ListenService.live!=null)ListenService.live.stop();});SystemClock.sleep(300);android.content.SharedPreferences.Editor edit=prefs.edit().putFloat("speed",speed);if(last==null)edit.remove("last");else edit.putString("last",last);edit.commit();if(file!=null){c.getSharedPreferences("listen_progress",0).edit().remove(file.getName()).commit();file.delete();}epub.delete();}}
}
